async function request(path3, init = {}, schema) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(`${API_BASE_URL}${path3}`, {
      ...init,
      headers: { "content-type": "application/json", ...init.headers ?? {} },
      signal: controller.signal
    });
    const body = await response.json().catch(() => void 0);
    if (!response.ok) {
      throw new Error(typeof body?.message === "string" ? body.message : `Edu-Pro API returned ${response.status}`);
    }
    return schema ? schema.parse(body) : body;
  } finally {
    clearTimeout(timeout);
  }
}
