  updateMentor: (id, body) => request(`/mentors/${encodeURIComponent(id)}`, { method: "PATCH", body: JSON.stringify(body) }, mentorSchema),
  listCategories: () => request("/categories", void 0, z2.array(categorySchema)),
  getCategory: (id) => request(`/categories/${encodeURIComponent(id)}`, void 0, categorySchema),
